cypher:
MATCH (r:Resolution)-[:HAS_DISPOSITION]->(d:DecisionDisposition {evidenceStatus:'source_verified'})-[:DISPOSITION_TARGET]->(t:Tdoc)-[:BELONGS_TO_CR_PACK]->(p:CRPack)
WHERE r.resolutionScope IS NULL AND d.assessmentMethod CONTAINS '"scope": "whole_target"' AND NOT EXISTS {
 MATCH (other:Resolution {resolutionScope:'document_disposition'})-[:HAS_DISPOSITION]->(verified:DecisionDisposition {evidenceStatus:'source_verified'})-[:DISPOSITION_TARGET]->(t)
 WHERE verified.assessmentMethod CONTAINS '"scope": "whole_target"'
}
RETURN count(DISTINCT t) AS documentsOnlyOldWholeScope, collect(DISTINCT {document:t.tdocNumber,pack:p.crPackId,assessment:d.assessmentMethod,content:substring(r.content,0,1000)})[0..3] AS examples
